def suslik_version():
    """Feste Versionsnummer aus der VERSION-Datei neben dem Code (ins Image gebacken, git-getaggt).
    'dev' wenn keine da (roher Lauf ohne Release). So weiss jeder laufende Container, WELCHE Version er ist."""
    try:
        with open(os.path.join(HERE, "VERSION")) as _f:
            return _f.read().strip() or "dev"
    except Exception:
        return "dev"


os.environ.setdefault("SUSLIK_VERSION", suslik_version())   # Docker-ENV gewinnt, sonst VERSION-Datei


def _version_neuer(tag, aktuell):
    """True, wenn ein Release-Tag (z.B. 'v0.1.0.28') NEUER ist als die laufende Version (#53).
    Beide Seiten tolerant zerlegt; unlesbar/leer -> False (nie einen falschen Hinweis zeigen)."""
    def teile(s):
        s = re.sub(r"^[vV]", "", str(s or "").strip())
        # Alpha-Release (30.07.): Namens-Suffix wie '-alpha' faellt fuer den VERGLEICH
        # weg — sonst koennte genau die Alpha-Installation nie einen Update-Hinweis
        # sehen (int('92-alpha') scheiterte -> Vergleich immer False).
        s = re.sub(r"[-+].*$", "", s)
        try:
            t = [int(x) for x in s.split(".") if x != ""]
        except ValueError:
            return None
        return t or None
    t, a = teile(tag), teile(aktuell)
    if not t or not a:
        return False
    n = max(len(t), len(a))
    return t + [0] * (n - len(t)) > a + [0] * (n - len(a))


# ------------------------------------------------------------------ Config
def _config_store_pfad(cfg):
    """Phase 2 (Docker-Richtung, User 21.07.): UI-geaenderte Werte liegen in einem JSON-Store
    <data_dir>/config.json, NICHT mehr per Zeilenersatz in der yaml. Die yaml ist die Basis
    (Defaults + Secrets via ${VAR}); der Store ueberlagert sie mit den Whitelist-Werten, die
    NUR ueber die UI/SaveConfig geschrieben werden (validiert). Kein ${VAR}-Risiko, kein
    kaputter yaml-Kommentar. Live-Reload + reine Env-Vars fuer Secrets kommen in Phase 4 (Docker)."""
    return os.path.join(cfg.get("data_dir") or os.path.join(HERE, "verify_data"), "config", "config.json")


def _lade_config_store(cfg):
    p = _config_store_pfad(cfg)
    if os.path.exists(p):
        try:
            with open(p) as f:                 # Datei sicher schliessen (frueher: offener Handle)
                d = json.load(f)
            return d if isinstance(d, dict) else {}
        except Exception as e:
            # NICHT still zu {} degradieren: der naechste Schreiber wuerde den Bestand ueberbuegeln.
            # Laut auf stderr (landet in `docker logs`) — hier gibt es noch kein svc.log().
            sys.stderr.write(f"[suslik] WARN: config store {p} unreadable ({e}) — "
                             f"yaml defaults apply; do NOT let the store be overwritten!\n")
    return {}


# Sieben Wege schreiben den Config-Store (config_schreiben, notif_speichern, config_wiederherstellen,
# Setup-Wizard, Kamera-Blatt, Areas, Sprache) — teils aus parallelen HTTP-Threads. Ohne gemeinsames Lock ist der
# Read-Modify-Write ein Race (letzter gewinnt, Aenderung des anderen weg), und mit dem FESTEN
# tmp-Namen "<p>.tmp" haetten sich zwei Schreiber gegenseitig die halbfertige Datei umbenannt.
# EHRLICH (Widerleger .91): das Lock deckt hier nur das SCHREIBEN; die fuenf Alt-Wege lesen den
# Store weiter ungeschuetzt davor (Race bleibt dort, entschaerft durch den folgenden neustart).
# Areas-Weg (.92) und Sprache-Weg (Stufe 1) laufen OHNE Neustart und halten das Lock um Lesen+Aendern+Schreiben —
# deshalb RLock (die verschachtelte Sperre in _store_schreiben darf nicht klemmen); die Alt-Wege
# auf denselben Griff umzustellen ist als Task notiert.
_cfg_lock = threading.RLock()


def _store_schreiben(p, store):
    """Config-Store atomar ablegen: pid-eigene tmp + flush + fsync + os.replace, unter _cfg_lock.
    Fehler werden NICHT verschluckt — der Aufrufer meldet sie."""
    os.makedirs(os.path.dirname(p), exist_ok=True)
    tmp = f"{p}.tmp-{os.getpid()}"
    with _cfg_lock:
        try:
            with open(tmp, "w") as f:
                json.dump(store, f, ensure_ascii=False, indent=1)
                f.flush()
                os.fsync(f.fileno())           # ohne fsync kann nach Stromausfall eine LEERE Datei
            os.replace(tmp, p)                 # unter dem gueltigen Namen stehen
        except Exception:
            try:
                os.remove(tmp)
            except OSError:
                pass
            raise


def _mask_secret(s):
    """Secret fuers Audit-Log NIE im Klartext: nur 'set' vs leer."""
    return "•••• set" if str(s or "") else ""


def _live_guards_aktiv(cfg):
    """Autostart-Praedikat des Live-Supervisors: mindestens ein enabled-Guard
    im STORE (frisch gelesen — Hand-Edits zaehlen, nicht die Prozess-Sicht).

    Widerleger phase34 MUSS-1: die alte Fassung urteilte mit roher bool()-
    Wahrheit (`g.get("enabled")`) — `"enabled": "false"` hielt der Supervisor
    fuer AN, die Engine (livewache._bool_lesen via guards_lesen) fuer AUS.
    Folge gemessen: Spawn -> "nothing to do" -> Fehlstart-Kette -> alle
    15 min ein Stoerungs-Push, fuer einen ausdruecklich abgeschalteten
    Waechter. EIN Praedikat fuer eine Frage (K3): dieselbe _bool_lesen-
    Wahrheit wie die Engine, kein Nachbau. Log dabei stumm — der Takt fragt
    alle 5 s, die LAUTE Meldung eines ungueltigen Werts gehoert der Engine
    (guards_lesen beim Start); der Default False ist derselbe."""
    from core import livewache as _lw
    with _cfg_lock:
        store = _lade_config_store(cfg)
    blk = (store.get("live") or {}).get("guards") or {}
    return any(isinstance(g, dict)
               and _lw._bool_lesen(g.get("enabled"), False, lambda z: None,
                                   f"live.guards.{name}.enabled")
               for name, g in blk.items())


def _pool_eid_karte(data_dir):
    """/heute-Blick in den Unbekannt-Pool -> (eid2uid, uid_members): Event-ID
    zu U-Nummer plus Mitglieder je Identitaet (fuer "seen Nx before").

    Widerleger phase34 MUSS-2: der /heute-Handler trug hier einen DRITTEN
    Streu-Parser derselben Datei — `{"members": 5}` warf `TypeError: 'int'
    object is not iterable` UNGEFANGEN in do_GET, die Seite starb (gemessen),
    waehrend der Harnisch nur das tolerante Modul prueft (K1). Deckungs-
    Regel: EIN Leser fuer die Datei (core.unbekanntpool._cluster_lesen —
    liefert nur Dicts) + Toleranz JE Cluster: eine kaputte Zeile kostet nur
    sich selbst, nie die Seite. Semantik unveraendert: objekt-Zeilen fallen
    raus (nie als "Unknown N" anbieten, 25.07.), Archiv-Cluster bleiben
    drin (Vorbesuchs-Zaehlung), members nur als Liste."""
    from core import unbekanntpool as _ubp
    eid2uid, uid_members = {}, {}
    for _d in _ubp._cluster_lesen(data_dir):
        try:
            _u = _d.get("uid") or _d.get("id")
            if not _u or _d.get("objekt"):
                continue
            _mem = _d.get("members")
            if not isinstance(_mem, list):
                _mem = []
            uid_members[_u] = _mem            # Mitglieder BEHALTEN, nicht nur
            for _m in _mem:                   # zaehlen: "seen Nx before"
                _s = str(_m)                  # braucht deren ZEITEN
                eid2uid.setdefault(_s, _u)
                # Top-3-Sammlung haengt ~2/~3 an die Event-ID — die Karte
                # matcht ueber die BASIS-Event-ID des Durchgangs
                eid2uid.setdefault(_s.split("~")[0], _u)
        except (TypeError, ValueError, AttributeError):
            continue
    return eid2uid, uid_members


def _migrate_layout(dd):
    """Einmalige, idempotente Migration flach -> Unterordner (config/ faces/ clips/ learn/ state/).
    `shutil.move` = Rename auf demselben Dateisystem (auch fuer die 77G clips instant, kein Kopieren).
    Nur wenn Quelle da UND Ziel fehlt -> gefahrlos bei jedem Start. Frisch = nur die Basisordner."""
    import shutil

    def mv(src, dst):
        s, d = os.path.join(dd, src), os.path.join(dd, dst)
        if os.path.exists(s) and not os.path.exists(d):
            os.makedirs(os.path.dirname(d) or dd, exist_ok=True)
            shutil.move(s, d)
    mv("refs", "faces")                                   # 1) ganze Verzeichnisse umbenennen
    mv("cache", "clips")
    mv("anlernen", "learn")
    mv("enroll", os.path.join("learn", "enroll"))         # 2) enroll unter learn
    # refcache bleibt in clips/ (kam mit cache->clips mit; geteilt mit analyze SCRATCH_DIR)
    for f in ("deckung.jsonl", "ground_truth.jsonl", "sublabel_writes.jsonl", "qs_bericht.json", "archiv"):
        mv(f, os.path.join("state", f))                   # 4) lose Logs/State -> state/
    for f in ("config.json", "config_audit.jsonl"):
        mv(f, os.path.join("config", f))                  # 5) Config -> config/
    for sub in ("config", "faces", "clips", "events", "learn", "state", "backups"):
        os.makedirs(os.path.join(dd, sub), exist_ok=True)  # 6) Basisordner sicherstellen (frisch)


ANKER_MIGRATION_MARKE = "migration_anker_045.json"   # state/, Muster kalib_reset.json
ANKER_ALT, ANKER_NEU = 0.50, 0.45


def _migration_anker_045(cfg):
    """EINMALIGE Anhebung des Urteils-Ankers 0,50 -> 0,45 (.510, User-Entscheid
    07.09.2026: "automatisch mit dieser Version einmalig ... wenn der User
    danach aendert, nicht wieder ueberschreiben").

    WARUM ueberhaupt: der Config-Store ueberlagert den Default-Block, und die
    Konfigurationsseite postet beim Sichern IMMER alle cfg-Felder. Jede
    Installation, auf der je "Speichern" gedrueckt wurde, hat den alten
    Werkswert 0,50 festgenagelt und saehe den neuen Default nie (Gegenpruefung
    W1, Befund M-6; beim Feldtester belegt).

    GENAU EINMAL, und der Marker haelt auch den NICHT-Eingriff fest (Muster
    core/kette.kette_auto und state/kalib_reset.json): steht die Marke, wird
    hier nie wieder etwas angefasst — auch dann nicht, wenn der Nutzer den
    Anker spaeter selbst auf 0,50 zurueckstellt. Marke im state/-Ordner statt
    im Store, weil ein Zurueckspielen einer alten Config-Sicherung die Marke
    sonst mitloeschen und die Migration ein zweites Mal ausloesen wuerde —
    dann ueber einen bewusst gesetzten Nutzerwert.

    Fallunterscheidung (alles andere ist Nutzerwille und bleibt):
      Store traegt exakt 0,50  -> auf 0,45, Audit-Zeile, Marke
      Store traegt anderen Wert -> unveraendert, nur Marke
      Store ohne den Schluessel -> unveraendert, nur Marke (Default greift)
      Store vorhanden, aber unlesbar -> NICHTS, auch keine Marke (naechster
        Start entscheidet ehrlich neu; sonst schriebe ein kaputter Store
        die ganze Config platt, s. dieselbe Wache in core/kette).

    Laeuft in load_config direkt nach der Store-Ueberlagerung, also VOR dem
    ersten Lesen des Ankers (run_analyze je Ereignis, Live-Engine beim Start).
    Meldung geht auf stderr — an dieser Stelle gibt es noch kein svc.log(),
    genau wie bei der Store-Warnung und der Whitelist-Klemmung daneben."""
    try:
        _migration_anker_045_innen(cfg)
    except Exception as e:                                     # noqa: BLE001
        # Eine gescheiterte Migration darf den Dienst NIE am Start hindern:
        # der Anker bleibt dann, wie er im Store steht, und der naechste Start
        # entscheidet neu (die Marke wird in diesem Fall nicht gesetzt).
        sys.stderr.write(f"[suslik] anchor migration failed "
                         f"({type(e).__name__}: {e}) — anchor unchanged, "
                         f"retried next start\n")


def _migration_anker_045_innen(cfg):
    """Der Rumpf von _migration_anker_045 (dort steht die Begruendung)."""
    marke = os.path.join(cfg["data_dir"], "state", ANKER_MIGRATION_MARKE)
    if os.path.exists(marke):
        return
    store_datei = _config_store_pfad(cfg)
    with _cfg_lock:
        store = _lade_config_store(cfg)
        if not store and os.path.exists(store_datei):
            sys.stderr.write("[suslik] anchor migration skipped: config store "
                             "exists but reads empty/unreadable — not touching "
                             "it (no marker; retried next start)\n")
            return
        alt = store.get("urteil_anker")
        try:
            trifft = alt is not None and abs(float(alt) - ANKER_ALT) < 1e-9
        except (TypeError, ValueError):
            trifft = False               # kaputter Typ ist kein Werkswert
        if trifft:
            store["urteil_anker"] = ANKER_NEU
            _store_schreiben(store_datei, store)
            cfg["urteil_anker"] = ANKER_NEU      # sofort wirksam, kein Neustart noetig
    info = {"ts": round(time.time(), 1),
            "version": os.environ.get("SUSLIK_VERSION", "dev"),
            "vorher": alt, "nachher": ANKER_NEU if trifft else alt,
            "angewendet": bool(trifft),
            "grund": "one-time factory-value change 0.50 -> 0.45 (2026-09-07)"}
    if trifft:
        # AUDIT VOR der Marke (Muster core/kette): die Marke ist aus der
        # Audit-Zeile rekonstruierbar, umgekehrt nicht — scheitert der
        # Markerschreiber, findet der naechste Start wenigstens die Herkunft.
        try:
            audit = os.path.join(cfg["data_dir"], "config", "config_audit.jsonl")
            os.makedirs(os.path.dirname(audit), exist_ok=True)
            with open(audit, "a") as f:
                f.write(json.dumps({"ts": info["ts"],
                                    "aenderungen": {"urteil_anker": ANKER_NEU},
                                    "auto": "one-time anchor migration 0.50 -> 0.45",
                                    "vorher": ANKER_ALT}, ensure_ascii=False) + "\n")
                f.flush()
        except Exception as e:                                 # noqa: BLE001
            sys.stderr.write(f"[suslik] anchor migration: audit line not written "
                             f"({type(e).__name__}: {e}) — value is in place\n")
        sys.stderr.write(f"[suslik] judgement anchor lifted ONCE for this install: "
                         f"{ANKER_ALT} -> {ANKER_NEU} (old factory value found in "
                         f"the config store; measured on 173 field cases 2026-09-07). "
                         f"Change it in Settings anytime — it will never be "
                         f"migrated again (marker state/{ANKER_MIGRATION_MARKE})\n")
    try:
        from core import atomar as _at
        _at.json_schreiben(marke, info)
    except Exception as e:                                     # noqa: BLE001
        sys.stderr.write(f"[suslik] anchor migration: marker not written "
                         f"({type(e).__name__}: {e}) — decision is retried next start\n")


STRAENGE_MIGRATION_MARKE = "migration_straenge_0535.json"   # state/, Muster oben
STRAENGE_ALT_MAX = 4          # die Obergrenze bis 0.1.0.534


def _migration_straenge_0535(cfg):
    """EINMALIGES Nachziehen der Obergrenze 4 -> 6 (.535, User-Entscheid
    15.09.2026: „bei dieser Version, wenn sie ausgerollt wird, den Max-Wert auf
    6 setzen, nicht dass draussen noch alte Werte stehen ... so dass ein User
    das nachtraeglich auch aendern kann").

    WARUM ueberhaupt: `STRAENGE_MAX` ist von 4 auf 6 gegangen (Feldmessung
    15.09.: drei Straenge lassen die Karte bei 55 % Mittel und 2769 von 12288
    MiB). Wer die alte Obergrenze im Store stehen hat — und das hat jeder, der
    den Regler je auf Anschlag gestellt hat —, saehe davon nichts: der Store
    ueberlagert den Default, und 4 bleibt 4. Dieselbe Klasse wie die
    Anker-Migration der .510.

    Fallunterscheidung (alles andere ist Nutzerwille und bleibt):
      Store traegt genau 4       -> auf 6, Audit-Zeile, Marke
      Store traegt 0 (Automatik) -> unveraendert, nur Marke
      Store traegt 1, 2, 3       -> unveraendert, nur Marke (bewusst kleiner)
      Store ohne den Schluessel  -> unveraendert, nur Marke
      Store vorhanden, unlesbar  -> NICHTS, auch keine Marke

    Betroffen sind BEIDE Schluessel, die an der Zahl hingen: `worker_straenge`
    (Rechenstraenge) und `analyse_plaetze` (gleichzeitige Analysen) — ihre
    Schema-Obergrenze kommt seit .535 aus derselben Konstante.

    Wie die Nachbarn: ein Fehler hindert den Start NIE, die Marke haelt auch den
    NICHT-Eingriff fest, und wer den Wert danach selbst aendert, behaelt ihn."""
    try:
        _migration_straenge_0535_innen(cfg)
    except Exception as e:                                     # noqa: BLE001
        sys.stderr.write(f"[suslik] thread-ceiling migration failed "
                         f"({type(e).__name__}: {e}) — values unchanged, "
                         f"retried next start\n")


def _migration_straenge_0535_innen(cfg):
    """Der Rumpf von _migration_straenge_0535 (dort steht die Begruendung)."""
    marke = os.path.join(cfg["data_dir"], "state", STRAENGE_MIGRATION_MARKE)
    if os.path.exists(marke):
        return
    neu_max = int(_gpubudget.STRAENGE_MAX)
    store_datei = _config_store_pfad(cfg)
    aenderungen = {}
    vorher = {}
    with _cfg_lock:
        store = _lade_config_store(cfg)
        if not store and os.path.exists(store_datei):
            sys.stderr.write("[suslik] thread-ceiling migration skipped: config "
                             "store exists but reads empty/unreadable — not "
                             "touching it (no marker; retried next start)\n")
            return
        for schluessel in ("worker_straenge", "analyse_plaetze"):
            alt = store.get(schluessel)
            try:
                trifft = alt is not None and int(alt) == STRAENGE_ALT_MAX
            except (TypeError, ValueError):
                trifft = False           # kaputter Typ ist keine Obergrenze
            if trifft and neu_max > STRAENGE_ALT_MAX:
                vorher[schluessel] = int(alt)
                aenderungen[schluessel] = neu_max
                store[schluessel] = neu_max
                cfg[schluessel] = neu_max     # sofort wirksam
        if aenderungen:
            _store_schreiben(store_datei, store)
    info = {"ts": round(time.time(), 1),
            "version": os.environ.get("SUSLIK_VERSION", "dev"),
            "vorher": vorher, "nachher": aenderungen,
            "alt_max": STRAENGE_ALT_MAX, "neu_max": neu_max,
            "angewendet": bool(aenderungen),
            "grund": f"one-time ceiling change {STRAENGE_ALT_MAX} -> {neu_max} "
                     f"(2026-09-15)"}
    if aenderungen:
        # AUDIT VOR der Marke (Muster Anker-Migration).
        try:
            audit = os.path.join(cfg["data_dir"], "config", "config_audit.jsonl")
            os.makedirs(os.path.dirname(audit), exist_ok=True)
            with open(audit, "a") as f:
                f.write(json.dumps(
                    {"ts": info["ts"], "aenderungen": aenderungen,
                     "auto": f"one-time migration: max compute threads/analysis "
                             f"slots {STRAENGE_ALT_MAX} -> {neu_max}, set "
                             f"explicitly, change it any time",
                     "vorher": vorher}, ensure_ascii=False) + "\n")
                f.flush()
        except Exception as e:                                 # noqa: BLE001
            sys.stderr.write(f"[suslik] thread-ceiling migration: audit line not "
                             f"written ({type(e).__name__}: {e}) — values are in "
                             f"place\n")
        was = ", ".join(f"{k} {vorher[k]} -> {v}" for k, v in sorted(aenderungen.items()))
        sys.stderr.write(f"[suslik] ceiling raised ONCE for this install: {was}. "
                         f"The old maximum was {STRAENGE_ALT_MAX}; a field "
                         f"measurement showed three threads leaving the card "
                         f"mostly idle, so the ceiling is now {neu_max}. The "
                         f"memory formula still decides what is really built — "
                         f"change the value in Settings any time, it will never "
                         f"be migrated again (marker "
                         f"state/{STRAENGE_MIGRATION_MARKE})\n")
    try:
        from core import atomar as _at
        _at.json_schreiben(marke, info)
    except Exception as e:                                     # noqa: BLE001
        sys.stderr.write(f"[suslik] thread-ceiling migration: marker not written "
                         f"({type(e).__name__}: {e}) — decision is retried next "
                         f"start\n")


EICH_AUS_MARKE = "migration_eich_aus_0535.json"      # state/, Muster oben
EICH_AUS_SCHLUESSEL = ("eich_fenster", "eich_planung")
EICH_AUS_DATEI = "vram_eichung.json"                 # state/, der Alt-Bestand


def _migration_eich_aus_0535(cfg):
    """EINMALIGES AUFRAEUMEN NACH DEM AUSBAU DER PREIS-MESSUNG (.535).

    WAS WEGFAELLT: die beiden Config-Schluessel `eich_fenster`/`eich_planung`
    und die Messdatei `state/vram_eichung.json`. Geplant wird seit .535 aus der
    Messtabelle in `core.gpubudget`; es gibt nichts mehr, was die beiden Zahlen
    steuern koennten, und nichts, was die Datei noch liest.

    WIE DER STORE UNBEKANNTE SCHLUESSEL BEHANDELT — nachgesehen, nicht vermutet
    (`load_config`, s. dort): der Store wird UNGEPRUEFT ueber die yaml-Basis
    gelegt (`for k, v in _lade_config_store(cfg).items(): cfg[k] = v`, nur
    `data_dir`/`web_port` sind tabu). Ein Schluessel, den niemand mehr liest,
    landet also in `cfg` und tut dort nichts; die Spannen-Klemme darunter laeuft
    ausdruecklich nur ueber Schluessel, die IN der Whitelist stehen. EIN START
    SCHEITERT DARAN NICHT — diese Migration ist deshalb Hygiene und kein
    Rettungsanker. Wo sie wirklich zieht: das Konfigurations-Blatt postet beim
    Speichern alle Felder, die es rendert, und `config_schreiben` weist einen
    Schluessel ausserhalb der Whitelist mit „ist nicht aenderbar" ab. Gerendert
    werden nur Whitelist-Schluessel, die beiden sind also schon aus dem Blatt
    verschwunden — die Zeile im Store waere nur noch eine Karteileiche, die bei
    jedem Blick in config.json Fragen aufwirft.

    Fallunterscheidung (dieselbe Bauform wie die Nachbarn darueber):
      Store traegt einen der Schluessel -> Zeile raus, Audit-Zeile, Marke
      Store ohne die Schluessel         -> unveraendert, nur Marke
      Store vorhanden, unlesbar         -> NICHTS, auch keine Marke
    Die Messdatei wird geloescht, wenn sie da ist; sie ist abgeleitetes
    Messmaterial, keine Nutzereingabe, und ohne Leser nur noch Ballast. Ein
    Fehler dabei hindert den Start NIE."""
    try:
        _migration_eich_aus_0535_innen(cfg)
    except Exception as e:                                     # noqa: BLE001
        sys.stderr.write(f"[suslik] calibration cleanup failed "
                         f"({type(e).__name__}: {e}) — nothing changed, "
                         f"retried next start\n")


def _migration_eich_aus_0535_innen(cfg):
    """Der Rumpf von _migration_eich_aus_0535 (dort steht die Begruendung)."""
    marke = os.path.join(cfg["data_dir"], "state", EICH_AUS_MARKE)
    if os.path.exists(marke):
        return
    store_datei = _config_store_pfad(cfg)
    entfernt = {}
    with _cfg_lock:
        store = _lade_config_store(cfg)
        if not store and os.path.exists(store_datei):
            sys.stderr.write("[suslik] calibration cleanup skipped: config store "
                             "exists but reads empty/unreadable — not touching it "
                             "(no marker; retried next start)\n")
            return
        for schluessel in EICH_AUS_SCHLUESSEL:
            if schluessel in store:
                entfernt[schluessel] = store.pop(schluessel)
            cfg.pop(schluessel, None)          # sofort wirksam, auch aus der yaml
        if entfernt:
            _store_schreiben(store_datei, store)
    # Die Messdatei — abgeleitet, ohne Leser, deshalb weg.
    datei = os.path.join(cfg["data_dir"], "state", EICH_AUS_DATEI)
    datei_weg = False
    try:
        if os.path.exists(datei):
            os.remove(datei)
            datei_weg = True
    except Exception as e:                                     # noqa: BLE001
        sys.stderr.write(f"[suslik] calibration cleanup: state/{EICH_AUS_DATEI} "
                         f"could not be removed ({type(e).__name__}: {e}) — it is "
                         f"unused either way\n")
    info = {"ts": round(time.time(), 1),
            "version": os.environ.get("SUSLIK_VERSION", "dev"),
            "entfernt": entfernt, "datei_geloescht": datei_weg,
            "angewendet": bool(entfernt or datei_weg),
            "grund": "price measurement removed in 0.1.0.535 — planning comes "
                     "from the measurement table (2026-09-15)"}
    if entfernt:
        try:
            audit = os.path.join(cfg["data_dir"], "config", "config_audit.jsonl")
            os.makedirs(os.path.dirname(audit), exist_ok=True)
            with open(audit, "a") as f:
                f.write(json.dumps(
                    {"ts": info["ts"], "aenderungen": {},
                     "auto": "one-time cleanup: the calibration keys are gone "
                             "(the service no longer measures prices, it plans "
                             "from the measurement table)",
                     "entfernt": entfernt}, ensure_ascii=False) + "\n")
                f.flush()
        except Exception as e:                                 # noqa: BLE001
            sys.stderr.write(f"[suslik] calibration cleanup: audit line not "
                             f"written ({type(e).__name__}: {e}) — the keys are "
                             f"gone either way\n")
        was = ", ".join(f"{k}={v}" for k, v in sorted(entfernt.items()))
        sys.stderr.write(f"[suslik] calibration settings removed ONCE for this "
                         f"install: {was}. Since 0.1.0.535 the service plans the "
                         f"card from a fixed measurement table instead of "
                         f"measuring its own prices, so neither key had anything "
                         f"left to steer (marker state/{EICH_AUS_MARKE})\n")
    try:
        from core import atomar as _at
        _at.json_schreiben(marke, info)
    except Exception as e:                                     # noqa: BLE001
        sys.stderr.write(f"[suslik] calibration cleanup: marker not written "
                         f"({type(e).__name__}: {e}) — decision is retried next "
                         f"start\n")


MIGRATION_0536_MARKE = "migration_0536.json"         # state/, Muster oben
# .536 B4.3/B5: die Schluessel, die mit dieser Version ihren Gegenstand
# verlieren. EINE Liste, EIN Marker fuer die ganze Version — ein zweiter Marker
# fuer dieselbe Version waere eine zweite Wahrheit.
MIGRATION_0536_SCHLUESSEL = ("hunger_bremse_s", "analyse_plaetze")
# Was der Betreiber im Audit-Log lesen soll — je Schluessel EIN Satz, in seinen
# Worten und nicht in unseren. Kein Personenname (Log-Vertrag §9).
MIGRATION_0536_SATZ = {
    "hunger_bremse_s": ("the 'hunger brake' setting ({wert}s) is gone — "
                        "background work now has its own slot and gets its "
                        "turn without holding up the event stream"),
    "analyse_plaetze": ("your old 'analysis slots' setting ({wert}) is no longer "
                        "a separate setting — the service now runs one analysis "
                        "slot per compute thread. Set 'Compute threads' if you "
                        "want fewer"),
}
# .536 B5: was nach dem Raeumen im laufenden `cfg` stehen soll. Fuer die
# Hunger-Bremse ist es NICHTS (der Schluessel ist ersatzlos weg, auch der
# Default-Eintrag). `analyse_plaetze` dagegen LEBT weiter als Experten-Override
# im Schema — geraeumt wird nur der alte NUTZER-Wert, und danach gilt wieder der
# Werkswert 0 = Automatik. Ohne diesen Eintrag stuende der Schluessel nach der
# Migration gar nicht mehr in `cfg`, und jeder Leser muesste „fehlt" ein zweites
# Mal als „0" auslegen.
MIGRATION_0536_WERK = {"analyse_plaetze": 0}


def _migration_0536(cfg):
    """EINMALIGES AUFRAEUMEN NACH DEM VERGABE-ZUG (.536, Bauplan §4.2).

    WAS WEGFAELLT: `hunger_bremse_s`. Die Bremse hielt den Ereignis-Strom bis zu
    120 s an, damit ein wartender Hintergrund-Job einen Analyse-Platz bekommt.
    Seit .536 haelt kein Hintergrund-Weg mehr einen Analyse-Platz — sie sitzen
    alle auf dem eigenen bg-Konto und bekommen ihren Zug dort. Es gibt nichts
    mehr vorzulassen, und eine Bremse ohne Gegenstand waere reiner Stillstand.

    WAS GERAEUMT WIRD: `analyse_plaetze` (B5/R7). Der Schluessel bleibt im Schema
    als Experten-Override, aber sein alter NUTZER-Wert wird entfernt und der
    Werkswert 0 (Automatik) gilt wieder. Drei Gruende, alle nachgeprueft:
      (a) Der Schluessel aendert seine BEDEUTUNG — von „wieviele Analysen
          gleichzeitig" zu „Drossel unter der Strangzahl". Ein alter Wert ist
          kein gueltiger Wert des neuen Schluessels.
      (b) Der GPU-Regler schrieb ihn bei JEDEM Speichern (bis .535
          `/gpu_speichern`), er steht also auf sehr vielen Anlagen, meist auf 1.
          Stehen gelassen drosselte er die Mehrheit still und dauerhaft auf EINEN
          Platz — R7 waere fuer sie wirkungslos.
      (c) Die .535-Migration hat gespeicherte 4 auf 6 gezogen, und zwar fuer
          BEIDE Schluessel. Ein Store kann heute `analyse_plaetze = 6` tragen,
          ohne dass je jemand sechs gewollt hat.
    Betreiber-Entscheid 3 vom 16.09. („nicht uebernommen, die Automatik gewinnt,
    Override nur kleiner") ist damit genau erfuellt. Eine UEBERNAHME nach
    `worker_straenge` findet ausdruecklich NICHT statt (User-Auflage W2-B16):
    vier Plaetze waren vier Prozesse, vier Straenge sind etwas anderes. Der
    Preis ist beziffert und gewollt: Bestandsanlagen springen beim Update von
    1 auf n Analyseplaetze — deshalb die laute Audit-Zeile mit dem ALTEN Wert.

    WARUM UEBERHAUPT RAEUMEN, wo ein unbekannter Schluessel doch nichts tut:
    dieselbe Begruendung wie bei `_migration_eich_aus_0535` (dort ausfuehrlich).
    Der Schluessel stand im Konfigurations-Blatt und kann deshalb auf jeder
    Anlage im Store liegen; als Karteileiche wirft er bei jedem Blick in
    config.json Fragen auf, und `config_schreiben` wuerde ihn kuenftig als
    „nicht aenderbar" abweisen.

    Fallunterscheidung (Bauform der Nachbarn darueber):
      Store traegt den Schluessel -> Zeile raus, Audit-Zeile, Marke
      Store ohne den Schluessel   -> unveraendert, nur Marke
      Store vorhanden, unlesbar   -> NICHTS, auch keine Marke
    Ein Fehler hindert den Start NIE; ein zweiter Lauf ist stumm (Marke)."""
    try:
        _migration_0536_innen(cfg)
    except Exception as e:                                     # noqa: BLE001
        sys.stderr.write(f"[suslik] .536 settings cleanup failed "
                         f"({type(e).__name__}: {e}) — nothing changed, "
                         f"retried next start\n")


def _migration_0536_innen(cfg):
    """Der Rumpf von _migration_0536 (dort steht die Begruendung)."""
    marke = os.path.join(cfg["data_dir"], "state", MIGRATION_0536_MARKE)
    if os.path.exists(marke):
        return
    store_datei = _config_store_pfad(cfg)
    entfernt = {}
    with _cfg_lock:
        store = _lade_config_store(cfg)
        if not store and os.path.exists(store_datei):
            sys.stderr.write("[suslik] .536 settings cleanup skipped: config "
                             "store exists but reads empty/unreadable — not "
                             "touching it (no marker; retried next start)\n")
            return
        for schluessel in MIGRATION_0536_SCHLUESSEL:
            drin = schluessel in store
            if drin:
                entfernt[schluessel] = store.pop(schluessel)
            if schluessel not in MIGRATION_0536_WERK:
                # Der Schluessel ist ersatzlos weg — dann auch aus der yaml,
                # sofort wirksam (er hat keinen Leser mehr).
                cfg.pop(schluessel, None)
            elif drin:
                # Der Schluessel LEBT als Experten-Override weiter. Geraeumt
                # wird deshalb genau der STORE-Wert (den die Oberflaeche
                # geschrieben hat), und in derselben Sitzung gilt wieder der
                # Werkswert — sonst truege `cfg` bis zum Neustart die Zahl, die
                # gerade geraeumt wurde.
                # EHRLICHE GRENZE: ein Hand-Eintrag in der yaml bleibt
                # unangetastet. Ihn hier zu nullen hiesse, ihn beim ERSTEN Start
                # zu verlieren und ab dem zweiten (Marke steht) wiederzuhaben —
                # zwei Verhalten derselben Anlage. Die yaml hat nie eine
                # Oberflaeche geschrieben; was dort steht, ist Absicht.
                cfg[schluessel] = MIGRATION_0536_WERK[schluessel]
        if entfernt:
            _store_schreiben(store_datei, store)
    saetze = [MIGRATION_0536_SATZ[k].format(wert=v)
              for k, v in sorted(entfernt.items()) if k in MIGRATION_0536_SATZ]
    info = {"ts": round(time.time(), 1),
            "version": os.environ.get("SUSLIK_VERSION", "dev"),
            "entfernt": entfernt, "angewendet": bool(entfernt),
            "grund": "0.1.0.536: background work has its own slot and analysis "
                     "slots follow the compute threads, the keys below lost "
                     "their subject (2026-09-16)"}
    if entfernt:
        # AUDIT VOR der Marke (Muster der Nachbar-Migrationen).
        try:
            audit = os.path.join(cfg["data_dir"], "config", "config_audit.jsonl")
            os.makedirs(os.path.dirname(audit), exist_ok=True)
            with open(audit, "a") as f:
                f.write(json.dumps(
                    {"ts": info["ts"], "aenderungen": {},
                     "auto": "one-time cleanup (0.1.0.536): " + "; ".join(saetze),
                     "entfernt": entfernt}, ensure_ascii=False) + "\n")
                f.flush()
        except Exception as e:                                 # noqa: BLE001
            sys.stderr.write(f"[suslik] .536 settings cleanup: audit line not "
                             f"written ({type(e).__name__}: {e}) — the keys are "
                             f"gone either way\n")
        for satz in saetze:
            sys.stderr.write(f"[suslik] {satz} (one-time, marker "
                             f"state/{MIGRATION_0536_MARKE})\n")
    try:
        from core import atomar as _at
        _at.json_schreiben(marke, info)
    except Exception as e:                                     # noqa: BLE001
        sys.stderr.write(f"[suslik] .536 settings cleanup: marker not written "
                         f"({type(e).__name__}: {e}) — decision is retried next "
                         f"start\n")


KATALOG_MIGRATION_MARKE = "migration_katalog_0125.json"   # state/, Muster oben


def _migration_katalog_0125(cfg):
    """EINMALIGE Ruecksetzung der KATALOG-Latte auf die neuen Werkswerte
    0,125/0,125 (.511, User-Entscheid 08.09.2026 ~17:0x: "0,125 passt, bau es
    so" — inkl. der ausdruecklichen Ansage "auch wenn der User das schon
    kalibriert hatte").

    WARUM: die alte Katalog-Latte lieh sich die NAH-Eichung des Lernlaufs
    (0,200/0,400) und wuergte damit die Automatik-Wege ab, die den Katalog
    ueberhaupt fuellen — am Feldtester-Spiegel kamen 34 von 200 Kalibrier-
    Samples durch. Mit dem Rollen-Zuschnitt vom 08.09. (aufnehmen liberal,
    sieben macht der Bestands-Pruefer) ist jeder gespeicherte Wert auf der
    ALTEN Skala gesetzt worden, egal ob Werkswert oder von Hand kalibriert.
    Deshalb setzt diese Migration BEIDE zurueck — anders als die Anker-
    Migration (.510), die einen selbst gesetzten Wert bewusst stehen liess.
    Der Unterschied ist gewollt und vom User so entschieden: hier wechselt
    nicht eine Zahl, hier wechselt die Bedeutung der Skala.

    WAS NICHT ANGEFASST WIRD: der Reiter "Erkennen" (det_min, guete_e_min,
    guete_t_min, pose_min) und die Pruefer-Latte. Wer seine Kameras fuer
    Anzeige/Meldung kalibriert hat, behaelt das vollstaendig.

    GENAU EINMAL, Marke im state/-Ordner (Muster _migration_anker_045): steht
    sie, wird hier nie wieder etwas angefasst — auch dann nicht, wenn der
    Nutzer die Katalog-Latte danach selbst wieder hochstellt. Sie liegt
    bewusst nicht im Store, weil ein zurueckgespieltes Config-Backup sie sonst
    mitloeschen und die Migration ein zweites Mal ausloesen wuerde.

    Store vorhanden, aber unlesbar -> NICHTS, auch keine Marke (der naechste
    Start entscheidet ehrlich neu; dieselbe Wache wie beim Anker)."""
    try:
        _migration_katalog_0125_innen(cfg)
    except Exception as e:                                     # noqa: BLE001
        sys.stderr.write(f"[suslik] catalogue-bar migration failed "
                         f"({type(e).__name__}: {e}) — bars unchanged, "
                         f"retried next start\n")


def _kat_gleich(alt, neu):
    """Traegt der Store schon den neuen Wert? Krumme/kaputte Werte gelten als
    UNGLEICH — die sollen erst recht auf den Werkswert."""
    try:
        return alt is not None and abs(float(alt) - float(neu)) < 1e-9
    except (TypeError, ValueError):
        return False


def _migration_katalog_0125_innen(cfg):
    """Der Rumpf von _migration_katalog_0125 (dort steht die Begruendung)."""
    from core.guete import KATALOG_STARTWERTE as _ks
    from core.kamerakalib import KAT_FELDER as _KATF
    marke = os.path.join(cfg["data_dir"], "state", KATALOG_MIGRATION_MARKE)
    if os.path.exists(marke):
        return
    neu_e, neu_t = float(_ks["empfinden"]), float(_ks["t"])
    # Feldnamen aus der EINEN Quelle (K3-Regel), Reihenfolge (e, t) wie dort.
    # Waechst KAT_FELDER, faellt das hier auf, statt still ein Feld auszulassen.
    kam_neu = dict(zip(_KATF, (neu_e, neu_t)))
    if len(kam_neu) != len(_KATF):
        sys.stderr.write(f"[suslik] catalogue-bar migration: kamerakalib."
                         f"KAT_FELDER has {len(_KATF)} fields, this migration "
                         f"knows {len(kam_neu)} — the rest is left untouched\n")
    glob_neu = {"katalog_guete_e_min": neu_e, "katalog_guete_t_min": neu_t}
    # [(bereich, {feld: alt}, {feld: neu})] — Bereich ist None fuer global,
    # sonst der Kameraname. Je Eintrag wird spaeter EINE Audit-Zeile geschrieben.
    aenderungen = []
    with _cfg_lock:
        store_datei = _config_store_pfad(cfg)
        store = _lade_config_store(cfg)
        if not store and os.path.exists(store_datei):
            sys.stderr.write("[suslik] catalogue-bar migration skipped: config "
                             "store exists but reads empty/unreadable — not "
                             "touching it (no marker; retried next start)\n")
            return
        vorher_g, nachher_g = {}, {}
        for feld, neu in glob_neu.items():
            alt = store.get(feld)
            # Nicht gesetzt = der (neue) Default greift ohnehin: nichts tun.
            if alt is None or _kat_gleich(alt, neu):
                continue
            store[feld] = neu
            cfg[feld] = neu                  # sofort wirksam, kein Neustart
            vorher_g[feld], nachher_g[feld] = alt, neu
        if vorher_g:
            aenderungen.append((None, vorher_g, nachher_g))
        guards = ((store.get("live") or {}).get("guards") or {})
        if isinstance(guards, dict):
            for name, blk in guards.items():
                if not isinstance(blk, dict):
                    continue                 # kaputter Block: guards_lesen meldet ihn
                vorher_k, nachher_k = {}, {}
                for feld, neu in kam_neu.items():
                    alt = blk.get(feld)
                    if alt is None or _kat_gleich(alt, neu):
                        continue
                    blk[feld] = neu
                    vorher_k[feld], nachher_k[feld] = alt, neu
                if vorher_k:
                    aenderungen.append((str(name), vorher_k, nachher_k))
        if aenderungen:
            _store_schreiben(store_datei, store)
            if "live" in store:
                cfg["live"] = store["live"]  # Prozess-Sicht sofort aktuell
    info = {"ts": round(time.time(), 1),
            "version": os.environ.get("SUSLIK_VERSION", "dev"),
            "neu": {"e": neu_e, "t": neu_t},
            "kameras": [n for n, _v, _n in aenderungen if n],
            "global": bool(aenderungen and aenderungen[0][0] is None),
            "angewendet": bool(aenderungen),
            "grund": "one-time catalogue-bar reset to the new factory values "
                     "0.125/0.125 (2026-09-08)"}
    # AUDIT VOR der Marke (Muster Anker-Migration): je geaenderter Stelle EINE
    # Zeile mit altem und neuem Wert — genau das, was ein Betreiber sucht, der
    # sich ueber die zurueckgesetzte Latte wundert.
    for name, vorher, nachher in aenderungen:
        try:
            audit = os.path.join(cfg["data_dir"], "config", "config_audit.jsonl")
            os.makedirs(os.path.dirname(audit), exist_ok=True)
            with open(audit, "a") as f:
                f.write(json.dumps(
                    {"ts": info["ts"],
                     "aenderungen": (nachher if name is None
                                     else {"live": {name: nachher}}),
                     "auto": "one-time catalogue-bar reset -> 0.125/0.125",
                     "vorher": vorher}, ensure_ascii=False) + "\n")
                f.flush()
        except Exception as e:                                 # noqa: BLE001
            sys.stderr.write(f"[suslik] catalogue-bar migration: audit line for "
                             f"{name or 'global'} not written "
                             f"({type(e).__name__}: {e}) — value is in place\n")
        wo = "global" if name is None else f"camera {name}"
        alt_txt = ", ".join(f"{k}={v}" for k, v in sorted(vorher.items()))
        sys.stderr.write(f"[suslik] catalogue bar reset ONCE for this install "
                         f"({wo}): {alt_txt} -> {neu_e}/{neu_t}. The old bar was "
                         f"far too strict for taking pictures in; the recognition "
                         f"tab is untouched. Re-calibrate it any time on the "
                         f"camera calibration page — it will never be migrated "
                         f"again (marker state/{KATALOG_MIGRATION_MARKE})\n")
    try:
        from core import atomar as _at
        _at.json_schreiben(marke, info)
    except Exception as e:                                     # noqa: BLE001
        sys.stderr.write(f"[suslik] catalogue-bar migration: marker not written "
                         f"({type(e).__name__}: {e}) — decision is retried next start\n")


def _placement_hw_key():
    """Fingerabdruck der Rechen-Hardware+Runtime fuers klebrige Placement: aendert sich
    CPU, Geraetesatz, onnxruntime oder die suslik-Version, wird neu gebenchmarkt."""
    import glob as _glob
    cpu = ""
    try:
        with open("/proc/cpuinfo") as f:
            for line in f:
                if line.startswith("model name"):
                    cpu = line.split(":", 1)[1].strip(); break
    except Exception:
        pass
    try:
        import onnxruntime as _ort
        ov = _ort.__version__
    except Exception:
        ov = "?"
    # /dev/kfd + /dev/nvidia*: ohne sie aendert ein AMD-/Nvidia-GPU-Wechsel den Key nicht und
    # ein altes Placement bliebe kleben (Inventur-Fund 31.07.). Key-Aenderung invalidiert
    # gespeicherte Placements einmalig — gewollt, naechster Boot misst neu.
    devs = sorted(_glob.glob("/dev/dri/renderD*")) + sorted(_glob.glob("/dev/accel/accel*")) \
         + sorted(_glob.glob("/dev/kfd")) + sorted(_glob.glob("/dev/nvidia[0-9]*"))
    return f"{cpu}|{','.join(devs)}|ort{ov}|{os.environ.get('SUSLIK_VERSION', '')}"


# Issue #21 (Tokn59, i5-5300U 2C/4T): die Wanduhr-Selbstmessung ist ein ZWEITER voller
# Analyse-Prozess neben dem Live-Worker. Sie darf nur laufen, wo ZWEI Analyse-Akteure
# nebeneinander passen — jeder Akteur besteht strukturell aus zwei nebenlaeufigen
# Bausteinen (ffmpeg-Decode + Inferenz, s. decode.FrameIter). Die 4 ist damit eine
# STRUKTUR-UNTERGRENZE (2 Akteure x 2 Bausteine, ein Axiom aus der Architektur),
# KEINE Messung — der Dienstprozess (Poll/MQTT/UI/Alerts) laeuft obendrauf und ist
# darin nicht einmal eingerechnet. Unter der Grenze ist die Messung Minuten Volllast
# fuer eine blosse Prognose-Komfortzahl UND misst dort vor allem die eigene
# Verdraengung statt der Maschine — ueberspringen, LAUT (K1: Startlog + /health
# sagen warum). Wer es auf einer kleinen Maschine BEWUSST will (z. B. nachts),
# senkt `wanduhr_min_kerne` in den Settings (CONFIG_WHITELIST) — ein Axiom darf
# keinen Nutzer endgueltig aussperren (Nachbesserung W2).
WANDUHR_AKTEURE = 2                # Live-Analyse + Mess-Roundtrip
WANDUHR_BAUSTEINE_JE_AKTEUR = 2    # ffmpeg-Decode + Inferenz je Akteur nebenlaeufig
WANDUHR_MIN_KERNE = WANDUHR_AKTEURE * WANDUHR_BAUSTEINE_JE_AKTEUR

